import{ax as e,A as r,aQ as t,z as o}from"./chunks/framework.BWRXlwpK.js";const u=JSON.parse('{"title":"前端自动化构建工具","description":"","frontmatter":{},"headers":[],"relativePath":"webpack/webpack-introduce.md","filePath":"webpack/webpack-introduce.md"}'),i={name:"webpack/webpack-introduce.md"};function l(n,a,s,c,d,p){return o(),r("div",null,a[0]||(a[0]=[t('<h1 id="前端自动化构建工具" tabindex="-1">前端自动化构建工具 <a class="header-anchor" href="#前端自动化构建工具" aria-label="Permalink to &quot;前端自动化构建工具&quot;">​</a></h1><h2 id="一、前端工程化" tabindex="-1">一、前端工程化： <a class="header-anchor" href="#一、前端工程化" aria-label="Permalink to &quot;一、前端工程化：&quot;">​</a></h2><p>前端工程化是根据业务特点，将前端开发流程<code>规范化</code>，<code>标准化</code>，它包括 <code>开发流程</code>，<code>技术选型</code>，<code>代码规范</code>，<code>构建发布</code>等，用于 <strong>提升前端工程师的开发效率和代码质量</strong>。</p><p>实现前端工程化的目的简单来说就是通过流程规范、自动化工具来提升前端的开发效率、性能、质量、多人协作以及开发体验。</p><p><strong>优点与目标</strong>：提升开发效率、性能、质量、多人协作以及开发体验</p><p><strong>具体实现</strong>：开发流程规范化，标准化，包括【开发流程、技术选型、代码规范、构建发布等】</p><h2 id="二、自动化构建工具" tabindex="-1">二、自动化构建工具： <a class="header-anchor" href="#二、自动化构建工具" aria-label="Permalink to &quot;二、自动化构建工具：&quot;">​</a></h2><p><strong>构建工具</strong>：将源代码转换成可以执行的JavaScript、CSS、HTML代码。</p><p>构建工具其实就是工程化、自动化思想在前端开发中的体现，将一系列流程用代码去实现，让代码自动化地执行这一系列复杂的流程。构建为前端开发注入更大的活力，解放了我们的生产力。</p><p>可实现的功能：</p><ul><li><strong>代码转换</strong>：将TypeScript编译成JavaScript、将SCSS编译成CSS。</li><li><strong>文件优化</strong>：将JavaScript、CSS、HTML代码，压缩恒诚图片等。</li><li><strong>代码分割</strong>：提取多个页面的公共代码，提起首屏不需要执行部分代码让其异步加载。</li><li><strong>模块合并</strong>：在采用模块化的项目里会有很多个模块和文件，需要通过构建功能将模块分类合并成一个文件。</li><li><strong>自动刷新</strong>：监听本地源代码变化，自动重新构建、刷新浏览器。</li><li><strong>代码校验</strong>：在代码被提交到仓库前需要校验代码是否符合规范，以及单元测试是否通过。</li><li><strong>自动发布</strong>：更新代码后，自动构建出线上发布代码并传输给发布系统。 。。。。</li></ul><h2 id="三、主流自动化构建工具" tabindex="-1">三、主流自动化构建工具： <a class="header-anchor" href="#三、主流自动化构建工具" aria-label="Permalink to &quot;三、主流自动化构建工具：&quot;">​</a></h2><ul><li>1.Grunt（基本不用）</li><li>2.Gulp（github受欢迎程度第二）</li><li>3.Fis（官方不更新维护了）</li><li>4.Webpack（github受欢迎程度第一）</li><li>。。。。</li></ul><h2 id="四、构建工具的选型-在开发中如何选择以上几种构件工具" tabindex="-1">四、构建工具的选型（在开发中如何选择以上几种构件工具）： <a class="header-anchor" href="#四、构建工具的选型-在开发中如何选择以上几种构件工具" aria-label="Permalink to &quot;四、构建工具的选型（在开发中如何选择以上几种构件工具）：&quot;">​</a></h2><ul><li>a.是否符合团队的技术栈</li><li>b.是否符合项目需求</li><li>c.生态是否完善、社区是否活跃</li></ul><h2 id="五、构建工具分类" tabindex="-1">五、构建工具分类： <a class="header-anchor" href="#五、构建工具分类" aria-label="Permalink to &quot;五、构建工具分类：&quot;">​</a></h2><p><strong>1.基于任务运行的工具</strong>：Grunt、Gulp 它们会自动执行指定的任务，就像流水线，把资源放上去然后通过不同插件进行加工，他们包含活跃的社区，丰富的插件，能方便的打造各种工作流。</p><p><strong>2.基于模块打包工具</strong>：Browserify、Webpack、rollup.js 有过Node.js开发经历的应该对模块很熟悉，需要引用组件直接一个require就OK，这类工具就是这个模式，还可以实现按需加载、异步加载模块。</p><p><strong>3.整合型工具</strong>：Yeoman、FIS、jdf、Athena等 使用了多种技术栈实现的脚手架工具，好处是即开即用，缺点是他们舒服了技术选型，并且学习成本相对较高。</p><h2 id="六、webpack优点" tabindex="-1">六、webPack优点： <a class="header-anchor" href="#六、webpack优点" aria-label="Permalink to &quot;六、webPack优点：&quot;">​</a></h2><ul><li>a.专注处理模块化的项目</li><li>b.可以通过plugin扩展，完整好用不失灵活</li><li>c.使用场景不局限web开发</li><li>d.社区活跃，紧跟时代发展特性</li><li>e.良好的开发体验</li></ul>',21)]))}const b=e(i,[["render",l]]);export{u as __pageData,b as default};
